/*
======================================================================
Creates a Stored Procedure: Load Gold Benchmarks
======================================================================
   This script creates a stored procedure to load the 'gold.fact_positional_benchmarks'
   and 'gold.fact_gk_benchmarks' table. This is an AGGREGATE table that materializes complex window functions
   (Percentiles, Medians) to ensure high performance for downstream BI tools.
   
   Logic:
    - Checks if the target table exists. If not, it auto-generates the schema.
    - TRUNCATES the table (Full Refresh of current benchmarks).
    - INSERTS calculated stats using Window Functions.

   Example: EXECUTE gold.load_gold;
======================================================================
*/

CREATE OR ALTER PROCEDURE gold.load_gold AS
BEGIN
    DECLARE @start_time DATETIME, @end_time DATETIME, @batch_start_time DATETIME, @batch_end_time DATETIME;
    BEGIN TRY
        SET @batch_start_time = GETDATE();
        PRINT '===================================================';
        PRINT 'LOADING GOLD LAYER';
        PRINT '===================================================';

--GOLD.FACT_POSITIONAL_BENCHMARKS
        PRINT '=============================================';
        PRINT 'GOLD.FACT_POSITIONAL_BENCHMARKS';
        PRINT '---------------------------------------------';
        PRINT 'LOADING DATA FROM: silver.fact_outfield_player_stats';
        PRINT 'LOADING DATA FROM: silver.dim_player_info';
        PRINT 'LOADING DATA FROM: silver.dim_team_info';
        PRINT '---------------------------------------------';
        SET @start_time = GETDATE();
        IF OBJECT_ID('gold.fact_positional_benchmarks', 'U') IS NULL
        PRINT '>>> Target table does not exist. Auto-generating schema...';
        SELECT TOP 0 
            A.team_key,
            A.league,
            A.club_name,
            C.position,
            CAST(0 AS INT) as total_minutes_played,
            CAST(0 AS DECIMAL(10,2)) as mean_minutes_played,
            CAST(0 AS DECIMAL(10,2)) as p25_minutes_played,
