            CAST(0 AS DECIMAL(10,2)) as p25_goals_outside_the_box,
            CAST(0 AS DECIMAL(10,2)) as median_goals_outside_the_box,
            CAST(0 AS DECIMAL(10,2)) as p75_goals_outside_the_box,
            CAST(0 AS DECIMAL(10,2)) as total_shots_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_shots_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_shots_per90,
            CAST(0 AS DECIMAL(10,2)) as median_shots_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_shots_per90,
            CAST(0 AS DECIMAL(10,2)) as total_xGoals_per_shot,
