            CAST(0 AS DECIMAL(10,2)) as median_open_play_key_passes_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_open_play_key_passes_per90,
            CAST(0 AS DECIMAL(10,2)) as total_chances_created_per90,
