            CAST(0 AS DECIMAL(10,2)) as p25_pressures_attempted_per90,
            CAST(0 AS DECIMAL(10,2)) as median_pressures_attempted_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_pressures_attempted_per90,
            CAST(0 AS DECIMAL(10,2)) as total_pressures_completed_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_pressures_completed_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_pressures_completed_per90,
            CAST(0 AS DECIMAL(10,2)) as median_pressures_completed_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_pressures_completed_per90,
            CAST(0 AS DECIMAL(10,2)) as total_possession_won_per90,
