            CAST(0 AS DECIMAL(10,2)) as median_key_tackles_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_key_tackles_per90,
            CAST(0 AS DECIMAL(10,2)) as total_interceptions_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_interceptions_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_interceptions_per90,
            CAST(0 AS DECIMAL(10,2)) as median_interceptions_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_interceptions_per90,
            CAST(0 AS DECIMAL(10,2)) as total_clearances_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_clearances_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_clearances_per90,
            CAST(0 AS DECIMAL(10,2)) as median_clearances_per90,
