            CAST(0 AS DECIMAL(10,2)) as total_blocks_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_blocks_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_blocks_per90,
            CAST(0 AS DECIMAL(10,2)) as median_blocks_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_blocks_per90,
