            CAST(0 AS DECIMAL(10,2)) as total_distance_covered_km_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_distance_covered_km_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_distance_covered_km_per90,
            CAST(0 AS DECIMAL(10,2)) as median_distance_covered_km_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_distance_covered_km_per90,
            CAST(0 AS DECIMAL(10,2)) as total_mistakes_leading_to_goals_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_mistakes_leading_to_goals_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_mistakes_leading_to_goals_per90,
            CAST(0 AS DECIMAL(10,2)) as median_mistakes_leading_to_goals_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_mistakes_leading_to_goals_per90,
            CAST(0 AS DECIMAL(10,2)) as total_fouls_made_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_fouls_made_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_fouls_made_per90,
            CAST(0 AS DECIMAL(10,2)) as median_fouls_made_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_fouls_made_per90,
            CAST(0 AS DECIMAL(10,2)) as total_fouls_against_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_fouls_against_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_fouls_against_per90,
            CAST(0 AS DECIMAL(10,2)) as median_fouls_against_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_fouls_against_per90,
            CAST(0 AS DECIMAL(10,2)) as total_yellow_cards_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_yellow_cards_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_yellow_cards_per90,
            CAST(0 AS DECIMAL(10,2)) as median_yellow_cards_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_yellow_cards_per90,
            CAST(0 AS DECIMAL(10,2)) as total_red_cards_per90,
            CAST(0 AS DECIMAL(10,2)) as mean_red_cards_per90,
            CAST(0 AS DECIMAL(10,2)) as p25_red_cards_per90,
            CAST(0 AS DECIMAL(10,2)) as median_red_cards_per90,
            CAST(0 AS DECIMAL(10,2)) as p75_red_cards_per90
        INTO gold.fact_positional_benchmarks
        FROM silver.dim_team_info AS A
        INNER JOIN silver.fact_outfield_player_stats AS B ON A.team_key = B.team_key
        INNER JOIN silver.dim_player_info AS C ON B.player_key = C.player_key
        WHERE 1 = 0; 
            
            PRINT '>>> Schema created successfully.';

        PRINT '>>> Truncating gold.fact_positional_benchmarks...';
        TRUNCATE TABLE gold.fact_positional_benchmarks;

        PRINT '>>> Calculating Benchmarks & Inserting New Records...';
        INSERT INTO gold.fact_positional_benchmarks
        SELECT DISTINCT
            A.team_key,
            A.league,
            A.club_name,
            C.position,
            SUM(B.minutes_played) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS total_minutes_played,
            AVG(B.minutes_played) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS mean_minutes_played,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.minutes_played) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS p25_minutes_played,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.minutes_played) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS median_minutes_played,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.minutes_played) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS p75_minutes_played,
            SUM(B.team_goals_scored_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS total_team_goals_scored_per90,
            AVG(B.team_goals_scored_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS mean_team_goals_scored_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.team_goals_scored_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS p25_team_goals_scored_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.team_goals_scored_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS median_team_goals_scored_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.team_goals_scored_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS p75_team_goals_scored_per90,
            SUM(B.team_goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS total_team_goals_conceded_per90,
            AVG(B.team_goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS mean_team_goals_conceded_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.team_goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS p25_team_goals_conceded_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.team_goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS median_team_goals_conceded_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.team_goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS p75_team_goals_conceded_per90,
            SUM(B.goals) OVER (PARTITION BY A.team_key, A.league, A.club_name, C.position) AS total_goals,
