            CAST(0 AS DECIMAL(10, 2)) as total_clearances_per90,
            CAST(0 AS DECIMAL(10, 2)) as mean_clearances_per90,
            CAST(0 AS DECIMAL(10, 2)) as p25_clearances_per90,
            CAST(0 AS DECIMAL(10, 2)) as median_clearances_per90,
            CAST(0 AS DECIMAL(10, 2)) as p75_clearances_per90,
            CAST(0 AS DECIMAL(10, 2)) as total_penalties_faced_per90,
            CAST(0 AS DECIMAL(10, 2)) as mean_penalties_faced_per90,
            CAST(0 AS DECIMAL(10, 2)) as p25_penalties_faced_per90,
            CAST(0 AS DECIMAL(10, 2)) as median_penalties_faced_per90,
            CAST(0 AS DECIMAL(10, 2)) as p75_penalties_faced_per90,
            CAST(0 AS DECIMAL(10, 2)) as total_penalties_save_percentage,
            CAST(0 AS DECIMAL(10, 2)) as mean_penalties_save_percentage,
            CAST(0 AS DECIMAL(10, 2)) as p25_penalties_save_percentage,
            CAST(0 AS DECIMAL(10, 2)) as median_penalties_save_percentage,
            CAST(0 AS DECIMAL(10, 2)) as p75_penalties_save_percentage,
            CAST(0 AS DECIMAL(10, 2)) as total_distance_covered_km_per90,
            CAST(0 AS DECIMAL(10, 2)) as mean_distance_covered_km_per90,
            CAST(0 AS DECIMAL(10, 2)) as p25_distance_covered_km_per90,
            CAST(0 AS DECIMAL(10, 2)) as median_distance_covered_km_per90,
            CAST(0 AS DECIMAL(10, 2)) as p75_distance_covered_km_per90,
            CAST(0 AS DECIMAL(10, 2)) as total_mistakes_leading_to_goals_per90,
            CAST(0 AS DECIMAL(10, 2)) as mean_mistakes_leading_to_goals_per90,
            CAST(0 AS DECIMAL(10, 2)) as p25_mistakes_leading_to_goals_per90,
            CAST(0 AS DECIMAL(10, 2)) as median_mistakes_leading_to_goals_per90,
            CAST(0 AS DECIMAL(10, 2)) as p75_mistakes_leading_to_goals_per90,
            CAST(0 AS DECIMAL(10, 2)) as total_fouls_against_per90,
            CAST(0 AS DECIMAL(10, 2)) as mean_fouls_against_per90,
            CAST(0 AS DECIMAL(10, 2)) as p25_fouls_against_per90,
            CAST(0 AS DECIMAL(10, 2)) as median_fouls_against_per90,
            CAST(0 AS DECIMAL(10, 2)) as p75_fouls_against_per90
        INTO gold.fact_gk_benchmarks
        FROM silver.dim_team_info AS A
        INNER JOIN silver.fact_gk_stats AS B ON A.team_key = B.team_key
        WHERE 1 = 0;
            
            PRINT '>>> Schema created successfully.';

        PRINT '>>> Truncating gold.fact_gk_benchmarks...';
        TRUNCATE TABLE gold.fact_gk_benchmarks;

        PRINT '>>> Calculating GK Benchmarks & Inserting New Records...';
        INSERT INTO gold.fact_gk_benchmarks
        SELECT DISTINCT
            A.team_key,
            A.league,
            A.club_name,
            SUM(B.minutes_played) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_minutes_played,
            AVG(B.minutes_played) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_minutes_played,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.minutes_played) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_minutes_played,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.minutes_played) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_minutes_played,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.minutes_played) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_minutes_played,
            SUM(B.team_goals_scored_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_team_goals_scored_per90,
            AVG(B.team_goals_scored_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_team_goals_scored_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.team_goals_scored_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_team_goals_scored_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.team_goals_scored_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_team_goals_scored_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.team_goals_scored_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_team_goals_scored_per90,
            SUM(B.team_goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_team_goals_conceded_per90,
            AVG(B.team_goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_team_goals_conceded_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.team_goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_team_goals_conceded_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.team_goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_team_goals_conceded_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.team_goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_team_goals_conceded_per90,
            SUM(B.goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_goals_conceded_per90,
            AVG(B.goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_goals_conceded_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_goals_conceded_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_goals_conceded_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.goals_conceded_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_goals_conceded_per90,
            SUM(B.saves_made_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_saves_made_per90,
            AVG(B.saves_made_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_saves_made_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.saves_made_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_saves_made_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.saves_made_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_saves_made_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.saves_made_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_saves_made_per90,
            SUM(B.xGoals_prevented_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_xGoals_prevented_per90,
            AVG(B.xGoals_prevented_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_xGoals_prevented_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.xGoals_prevented_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_xGoals_prevented_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.xGoals_prevented_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_xGoals_prevented_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.xGoals_prevented_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_xGoals_prevented_per90,
            AVG(B.xSave_rate) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_xSave_rate,
            AVG(B.xSave_rate) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_xSave_rate,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.xSave_rate) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_xSave_rate,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.xSave_rate) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_xSave_rate,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.xSave_rate) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_xSave_rate,
            SUM(B.saves_tipped_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_saves_tipped_per90,
            AVG(B.saves_tipped_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_saves_tipped_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.saves_tipped_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_saves_tipped_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.saves_tipped_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_saves_tipped_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.saves_tipped_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_saves_tipped_per90,
            SUM(B.saves_parried_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_saves_parried_per90,
            AVG(B.saves_parried_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_saves_parried_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.saves_parried_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_saves_parried_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.saves_parried_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_saves_parried_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.saves_parried_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_saves_parried_per90,
            SUM(B.saves_held_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_saves_held_per90,
            AVG(B.saves_held_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_saves_held_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.saves_held_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_saves_held_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.saves_held_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_saves_held_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.saves_held_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_saves_held_per90,
            AVG(B.saves_percentage) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_saves_percentage,
            AVG(B.saves_percentage) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_saves_percentage,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.saves_percentage) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_saves_percentage,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.saves_percentage) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_saves_percentage,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.saves_percentage) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_saves_percentage,
            SUM(B.passes_attempted_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_passes_attempted_per90,
            AVG(B.passes_attempted_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_passes_attempted_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.passes_attempted_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_passes_attempted_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.passes_attempted_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_passes_attempted_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.passes_attempted_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_passes_attempted_per90,
            AVG(B.pass_accuracy) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_pass_accuracy,
            AVG(B.pass_accuracy) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_pass_accuracy,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.pass_accuracy) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_pass_accuracy,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.pass_accuracy) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_pass_accuracy,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.pass_accuracy) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_pass_accuracy,
            SUM(B.possession_won_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_possession_won_per90,
            AVG(B.possession_won_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_possession_won_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.possession_won_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_possession_won_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.possession_won_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_possession_won_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.possession_won_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_possession_won_per90,
            SUM(B.possession_lost_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_possession_lost_per90,
            AVG(B.possession_lost_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_possession_lost_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.possession_lost_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_possession_lost_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.possession_lost_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_possession_lost_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.possession_lost_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_possession_lost_per90,
            SUM(B.interceptions_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_interceptions_per90,
            AVG(B.interceptions_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_interceptions_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.interceptions_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_interceptions_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.interceptions_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_interceptions_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.interceptions_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_interceptions_per90,
            SUM(B.clearances_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_clearances_per90,
            AVG(B.clearances_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_clearances_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.clearances_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_clearances_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.clearances_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_clearances_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.clearances_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_clearances_per90,
            SUM(B.penalties_faced_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_penalties_faced_per90,
            AVG(B.penalties_faced_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_penalties_faced_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.penalties_faced_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_penalties_faced_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.penalties_faced_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_penalties_faced_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.penalties_faced_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_penalties_faced_per90,
            AVG(B.penalties_save_percentage) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_penalties_save_percentage,
            AVG(B.penalties_save_percentage) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_penalties_save_percentage,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.penalties_save_percentage) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_penalties_save_percentage,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.penalties_save_percentage) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_penalties_save_percentage,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.penalties_save_percentage) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_penalties_save_percentage,
            SUM(B.distance_covered_km_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_distance_covered_km_per90,
            AVG(B.distance_covered_km_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_distance_covered_km_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.distance_covered_km_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_distance_covered_km_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.distance_covered_km_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_distance_covered_km_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.distance_covered_km_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_distance_covered_km_per90,
            SUM(B.mistakes_leading_to_goals_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_mistakes_leading_to_goals_per90,
            AVG(B.mistakes_leading_to_goals_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_mistakes_leading_to_goals_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.mistakes_leading_to_goals_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_mistakes_leading_to_goals_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.mistakes_leading_to_goals_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_mistakes_leading_to_goals_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.mistakes_leading_to_goals_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_mistakes_leading_to_goals_per90,
            SUM(B.fouls_against_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS total_fouls_against_per90,
            AVG(B.fouls_against_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS mean_fouls_against_per90,
            PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY B.fouls_against_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p25_fouls_against_per90,
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY B.fouls_against_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS median_fouls_against_per90,
            PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY B.fouls_against_per90) OVER (PARTITION BY A.team_key, A.league, A.club_name) AS p75_fouls_against_per90
        FROM silver.dim_team_info AS A
        INNER JOIN silver.fact_gk_stats AS B
            ON A.team_key = B.team_key
        WHERE A.dwh_current_validity = 1;

        SET @end_time = GETDATE();
        PRINT '---------------------------------------------';
        PRINT '>>DURATION: ' + CAST(DATEDIFF(millisecond, @start_time, @end_time) AS NVARCHAR) + ' milliseconds';
        PRINT '---------------------------------------------';

        SET @batch_end_time = GETDATE();
        PRINT '=================================';
        PRINT 'LOADING OF GOLD LAYER COMPLETED';
        PRINT 'TOTAL DURATION: ' + CAST(DATEDIFF(millisecond, @batch_start_time, @batch_end_time) AS NVARCHAR) + ' milliseconds';
        PRINT '=================================';
    END TRY
    BEGIN CATCH
        PRINT '=================================';
        PRINT 'ERROR DURING LOADING GOLD BENCHMARKS';
        PRINT 'Error Message:' + ERROR_MESSAGE();
        PRINT 'Error Message:' + CAST(ERROR_NUMBER() AS NVARCHAR);
        PRINT 'Error Message:' + CAST(ERROR_STATE() AS NVARCHAR);
        PRINT '=================================';
    END CATCH
END